#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> dist(n, vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> dist[i][j];
        }
    }

    const long long INF = 1000000000000000000LL;
    int cities = (int)n;
    int full = (1 << cities) - 1;
    vector<vector<long long>> best(1 << cities, vector<long long>(cities, INF));
    best[1][0] = 0;
    for (int mask = 1; mask <= full; mask++) {
        for (int last = 0; last < cities; last++) {
            long long cur = best[mask][last];
            if (cur == INF) continue;
            for (int nxt = 0; nxt < cities; nxt++) {
                if (mask >> nxt & 1) continue;
                int nm = mask | (1 << nxt);
                best[nm][nxt] = min(best[nm][nxt], cur + dist[last][nxt]);
            }
        }
    }
    long long answer = INF;
    for (int v = 1; v < cities; v++) answer = min(answer, best[full][v] + dist[v][0]);
    cout << answer << "\n";

    return 0;
}

